<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'; import AppShell from '@/layouts/AppShell.vue'; import PageHeader from '@/components/PageHeader.vue'; import PanelCard from '@/components/PanelCard.vue'; import StatusPill from '@/components/StatusPill.vue'; import { connect } from '@/services/connect'; import type { ConnectionItem } from '@/types/domain'; const items=ref<ConnectionItem[]>([]); onMounted(async()=>{items.value=await connect.connections().catch(()=>[])}); const groups=computed(()=>Object.values(items.value.reduce((acc:any,i)=>{acc[i.channel] ||= {name:i.channel,total:0,connected:0};acc[i.channel].total++;if(i.status==='connected')acc[i.channel].connected++;return acc},{})))
</script>
<template><AppShell><PageHeader title="Canais" description="Acompanhe os canais de comunicação disponíveis."/><div class="channel-grid"><PanelCard v-for="item in groups" :key="item.name"><div class="channel-card"><span class="channel-icon">{{item.name.slice(0,1)}}</span><div><h3>{{item.name}}</h3><p>{{item.connected}} de {{item.total}} conexões ativas</p></div><StatusPill :status="item.connected===item.total?'ok':'attention'"/></div></PanelCard></div></AppShell></template>
